From 597f5f85ff1e070da6023ca2b6f55fc072a0e272 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sun, 22 Nov 2026 02:54:55 +0100
Subject: [PATCH] plasmaquick: add an obscured property to applets

Applets had no way to know they can't be seen, so a desktop widget kept
running live meters and animations under windows. Containments can now
mark an applet as obscured, and applets can pause such work while it is.

BUG: 441555
---
 src/plasmaquick/appletquickitem.cpp | 15 +++++++++++++++
 src/plasmaquick/appletquickitem.h   | 17 +++++++++++++++++
 src/plasmaquick/appletquickitem_p.h |  1 +
 3 files changed, 33 insertions(+)

diff --git a/src/plasmaquick/appletquickitem.cpp b/src/plasmaquick/appletquickitem.cpp
index ab3fa7ebb..7db0f9124 100644
--- a/src/plasmaquick/appletquickitem.cpp
+++ b/src/plasmaquick/appletquickitem.cpp
@@ -959,6 +959,21 @@ void AppletQuickItem::setBadgeText(const QString &text)
     Q_EMIT badgeTextChanged(text);
 }

+bool AppletQuickItem::isObscured() const
+{
+    return d->obscured;
+}
+
+void AppletQuickItem::setObscured(bool obscured)
+{
+    if (d->obscured == obscured) {
+        return;
+    }
+
+    d->obscured = obscured;
+    Q_EMIT obscuredChanged(obscured);
+}
+
 ////////////Internals

 QQuickItem *AppletQuickItem::compactRepresentationItem()
diff --git a/src/plasmaquick/appletquickitem.h b/src/plasmaquick/appletquickitem.h
index 91c7473af..f7f825da7 100644
--- a/src/plasmaquick/appletquickitem.h
+++ b/src/plasmaquick/appletquickitem.h
@@ -119,6 +119,18 @@ class PLASMAQUICK_EXPORT AppletQuickItem : public QQuickItem
      */
     Q_PROPERTY(QString badgeText READ badgeText WRITE setBadgeText NOTIFY badgeTextChanged)

+    /*!
+     * True while the applet can't be seen at all, for example a desktop widget
+     * completely covered by windows. The containment sets it; applets can use
+     * it to pause work that only matters while they are seen, such as live
+     * meters or animations.
+     *
+     * The default value is \c false.
+     *
+     * \since 6.9
+     */
+    Q_PROPERTY(bool obscured READ isObscured WRITE setObscured NOTIFY obscuredChanged)
+
 public:
     AppletQuickItem(QQuickItem *parent = nullptr);
     ~AppletQuickItem() override;
@@ -166,6 +178,9 @@ public:
     QString badgeText() const;
     void setBadgeText(const QString &text);

+    bool isObscured() const;
+    void setObscured(bool obscured);
+
     static bool hasItemForApplet(Plasma::Applet *applet);
     static AppletQuickItem *itemForApplet(Plasma::Applet *applet);

@@ -192,6 +207,8 @@ Q_SIGNALS:

     void badgeTextChanged(QString text);

+    void obscuredChanged(bool obscured);
+
 protected:
     // Initializations that need to be executed after classBegin()
     virtual void init();
diff --git a/src/plasmaquick/appletquickitem_p.h b/src/plasmaquick/appletquickitem_p.h
index 1cf2e80ad..bf16b89c5 100644
--- a/src/plasmaquick/appletquickitem_p.h
+++ b/src/plasmaquick/appletquickitem_p.h
@@ -113,6 +113,7 @@ public:
     bool preloadFullRepresentation = false;
     bool expandedOnDragHover = false;
     bool activationTogglesExpanded = true;
+    bool obscured = false;
     bool initComplete : 1;
     bool compactRepresentationCheckGuard : 1;

