From a4ba7f7f607aaead32d39b582eb7228eab91dcc0 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sun, 22 Nov 2026 02:54:55 +0100
Subject: [PATCH] containments/desktop: mark applets covered by windows as
 obscured

Widgets on the desktop always counted as visible, even when windows hid
them completely. The desktop now tracks the windows on its screen and
marks each applet as obscured while they cover it, wherever it is moved.

BUG: 441555
---
 .../desktop/package/contents/ui/main.qml      | 102 ++++++++++++++++++
 1 file changed, 102 insertions(+)

diff --git a/containments/desktop/package/contents/ui/main.qml b/containments/desktop/package/contents/ui/main.qml
index d3f413b2df..394cd8fffd 100644
--- a/containments/desktop/package/contents/ui/main.qml
+++ b/containments/desktop/package/contents/ui/main.qml
@@ -14,6 +14,8 @@ import org.kde.plasma.plasmoid
 import org.kde.plasma.core as PlasmaCore
 import org.kde.ksvg as KSvg
 import org.kde.kirigami as Kirigami
+import org.kde.kwindowsystem
+import org.kde.taskmanager as TaskManager

 import org.kde.private.desktopcontainment.folder as Folder

@@ -102,6 +104,92 @@ ContainmentItem {

     onScreenChanged: isUiReady = Plasmoid.containment.corona.isScreenUiReady(root.screen)

+    // Geometries of the windows over this desktop; applets they cover completely are obscured
+    property list<rect> coveringWindows: []
+
+    Loader {
+        active: root.isContainment
+
+        sourceComponent: Item {
+            TaskManager.TasksModel {
+                id: windowsModel
+
+                filterByCurrentVirtualDesktop: true
+                filterByActivity: true
+                filterByRegion: TaskManager.RegionFilterMode.Intersect
+                filterHidden: true
+                filterMinimized: true
+
+                regionGeometry: root.screenGeometry
+                activity: activityInfo.currentActivity
+
+                groupMode: TaskManager.TasksModel.GroupDisabled
+
+                function updateCoveringWindows(): void {
+                    const windows = [];
+                    for (let i = 0; i < count; ++i) {
+                        windows.push(data(index(i, 0), TaskManager.AbstractTasksModel.Geometry));
+                    }
+                    root.coveringWindows = windows;
+                }
+
+                onCountChanged: Qt.callLater(windowsModel.updateCoveringWindows)
+                onModelReset: Qt.callLater(windowsModel.updateCoveringWindows)
+                onDataChanged: (topLeft, bottomRight, roles) => {
+                    if (roles.length === 0 || roles.includes(TaskManager.AbstractTasksModel.Geometry)) {
+                        Qt.callLater(windowsModel.updateCoveringWindows);
+                    }
+                }
+                Component.onCompleted: updateCoveringWindows()
+            }
+
+            TaskManager.ActivityInfo {
+                id: activityInfo
+            }
+        }
+    }
+
+    function windowsCover(area: rect): bool {
+        if (KWindowSystem.showingDesktop || area.width <= 0 || area.height <= 0) {
+            return false;
+        }
+
+        // Cut each window out of the area and see if anything is left
+        let uncovered = [{ left: area.x, top: area.y, right: area.x + area.width, bottom: area.y + area.height }];
+        for (const window of coveringWindows) {
+            const left = window.x;
+            const top = window.y;
+            const right = window.x + window.width;
+            const bottom = window.y + window.height;
+            const remaining = [];
+            for (const r of uncovered) {
+                if (left >= r.right || top >= r.bottom || right <= r.left || bottom <= r.top) {
+                    remaining.push(r);
+                    continue;
+                }
+                const middleTop = Math.max(r.top, top);
+                const middleBottom = Math.min(r.bottom, bottom);
+                if (top > r.top) {
+                    remaining.push({ left: r.left, top: r.top, right: r.right, bottom: top });
+                }
+                if (bottom < r.bottom) {
+                    remaining.push({ left: r.left, top: bottom, right: r.right, bottom: r.bottom });
+                }
+                if (left > r.left) {
+                    remaining.push({ left: r.left, top: middleTop, right: left, bottom: middleBottom });
+                }
+                if (right < r.right) {
+                    remaining.push({ left: right, top: middleTop, right: r.right, bottom: middleBottom });
+                }
+            }
+            if (remaining.length === 0) {
+                return true;
+            }
+            uncovered = remaining;
+        }
+        return false;
+    }
+
     // We want to do this here rather than in the model because we don't always want
     // symbolic icons everywhere, but we do know that we always want them in this
     // specific representation right here
@@ -342,6 +430,20 @@ ContainmentItem {
                     applet.visible = true
                 }

+                // The desktop fills its screen, so this is where the applet is on it
+                readonly property rect screenRect: Qt.rect(root.screenGeometry.x + dropArea.x + x,
+                                                           root.screenGeometry.y + dropArea.y + y,
+                                                           width, height)
+
+                Binding {
+                    target: appletContainer.applet
+                    property: "obscured"
+                    // An open popup isn't covered by the windows
+                    value: root.windowsCover(appletContainer.screenRect)
+                        && !(appletContainer.applet.expanded && (appletContainer.applet.compactRepresentationItem?.visible ?? false))
+                    when: appletContainer.applet !== null
+                }
+
                 Drag.dragType: Drag.Automatic
                 Drag.active: false
                 Drag.supportedActions: Qt.MoveAction
-- 
